#!/usr/bin/env node
/**
 * Builds the five soak/RC fixture videos (§52).
 *
 * They are deliberately unlike each other — different lengths, resolutions,
 * frame rates, sample rates and channel counts — so that normalization and the
 * concat boundaries are genuinely exercised. Nothing copyrighted is used or
 * committed; every clip is generated by FFmpeg.
 */
import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const DIR = join(ROOT, 'tests/fixtures/rc')
mkdirSync(DIR, { recursive: true })

function ffmpeg() {
  for (const t of ['x86_64-unknown-linux-gnu', 'aarch64-unknown-linux-gnu', 'x86_64-apple-darwin', 'aarch64-apple-darwin', 'x86_64-pc-windows-msvc']) {
    const ext = t.includes('windows') ? '.exe' : ''
    const p = join(ROOT, 'apps/desktop/src-tauri/binaries', `ffmpeg-${t}${ext}`)
    if (existsSync(p)) return p
  }
  return 'ffmpeg'
}

const SPECS = [
  { name: 'rc_01', secs: 95,  size: '1280x720',  fps: 25, rate: 44100, ch: 2, tone: 440, pattern: 'testsrc2' },
  { name: 'rc_02', secs: 62,  size: '1920x1080', fps: 30, rate: 48000, ch: 2, tone: 523, pattern: 'smptebars' },
  { name: 'rc_03', secs: 128, size: '854x480',   fps: 24, rate: 32000, ch: 1, tone: 659, pattern: 'testsrc' },
  { name: 'rc_04', secs: 47,  size: '1920x1080', fps: 60, rate: 48000, ch: 2, tone: 784, pattern: 'testsrc2' },
  { name: 'rc_05', secs: 83,  size: '640x360',   fps: 15, rate: 22050, ch: 2, tone: 880, pattern: 'smptebars' },
]

const bin = ffmpeg()
for (const s of SPECS) {
  const out = join(DIR, `${s.name}.mp4`)
  if (existsSync(out)) { console.log(`exists  ${s.name}.mp4`); continue }
  process.stdout.write(`building ${s.name}.mp4 (${s.secs}s, ${s.size}, ${s.fps}fps, ${s.rate}Hz, ${s.ch}ch)… `)
  const r = spawnSync(bin, [
    '-hide_banner', '-loglevel', 'error', '-y',
    '-f', 'lavfi', '-i', `${s.pattern}=size=${s.size}:rate=${s.fps}:duration=${s.secs}`,
    '-f', 'lavfi', '-i', `sine=frequency=${s.tone}:sample_rate=${s.rate}:duration=${s.secs}`,
    '-c:v', 'libx264', '-preset', 'ultrafast', '-pix_fmt', 'yuv420p',
    '-c:a', 'aac', '-ar', String(s.rate), '-ac', String(s.ch), '-shortest', out,
  ], { stdio: ['ignore', 'ignore', 'pipe'] })
  if (r.status !== 0) {
    console.log('FAILED')
    console.error(String(r.stderr).slice(0, 400))
    process.exit(1)
  }
  console.log('ok')
}
console.log(`\nfixtures in ${DIR}`)
